"use client";

import { useEffect, useState } from "react";
import { Check } from "lucide-react";

export default function PackagesPage() {
  const [packages, setPackages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/packages")
      .then(res => res.json())
      .then(data => {
        setPackages(data.packages || []);
        setLoading(false);
      })
      .catch(() => {
        setPackages([]);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="p-8">Loading...</p>;

  return (
    <div className="py-8 px-6">
      <div className="text-center mb-8">
        <div className="inline-flex items-center gap-2 text-sm text-gray-600 mb-6">
          <Check size={16} className="text-green-600" />
          100% Money-back Guarantee
        </div>
      </div>

      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {packages.map((pkg) => (
          <div
            key={pkg.id}
            className={`rounded-xl border p-6 flex flex-col ${
              pkg.isPopular
                ? "bg-gray-900 text-white border-gray-900"
                : "bg-white text-gray-900 border-gray-200"
            }`}
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-xl font-semibold">{pkg.name}</h3>
              {pkg.isPopular && (
                <span className="bg-white text-gray-900 text-xs px-2 py-1 rounded">
                  Popular
                </span>
              )}
            </div>

            <div className="mb-6">
              <div className="text-3xl font-bold">
                ${pkg.price}
              </div>
              <div className={`text-sm mt-1 ${pkg.isPopular ? "text-gray-400" : "text-gray-500"}`}>
                Per user/month, billed yearly
              </div>
            </div>

            <button
              className={`w-full py-2.5 rounded-lg font-medium mb-6 transition ${
                pkg.isPopular
                  ? "bg-white text-gray-900 hover:bg-gray-100"
                  : "bg-gray-100 text-gray-900 hover:bg-gray-200"
              }`}
            >
              Get started
            </button>

            <div className="border-t pt-4 mb-4" style={{ borderColor: pkg.isPopular ? '#374151' : '#e5e7eb' }}>
              <div className={`text-xs font-semibold mb-3 uppercase tracking-wide ${
                pkg.isPopular ? "text-gray-400" : "text-gray-500"
              }`}>
                KEY FEATURES:
              </div>
            </div>

            <ul className="space-y-2.5 text-sm">
              {pkg.features.map((feature: string, idx: number) => (
                <li key={idx} className="flex items-start gap-2">
                  <Check size={16} className={`mt-0.5 flex-shrink-0 ${pkg.isPopular ? "text-white" : "text-gray-700"}`} />
                  <span className={pkg.isPopular ? "text-gray-100" : "text-gray-700"}>{feature}</span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}